css:
.rows {
  display: grid;
  gap: 20px;
  padding: 24px;
  font-family: system-ui, sans-serif;
}

.row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.tag {
  padding: 6px 12px;
  border-radius: 999px;
  background-color: #ffedd5;
  cursor: pointer;
}

.grows:hover {
  border: 3px solid #ea580c;
}

.outlined:hover {
  outline: 3px solid #ea580c;
}

.reserved {
  border: 3px solid transparent;
}

.reserved:hover {
  border-color: #ea580c;
}
